const BK = (t, a, y, cat, idea, claves, aplica, frase) => ["<span class='bkh'>" + t + "</span> · " + a + " (" + y + ")", "<p class='eyebrow' style='margin:0 0 6px'>" + cat + "</p><p><b>Idea central.</b> " + idea + "</p><h4>Ideas clave</h4><ul>" + claves.map(c => "<li>" + c + "</li>").join("") + "</ul><h4>Cómo aplicarlo como ingeniero</h4>" + aplica + (frase ? "<blockquote class='cita'>" + frase + "</blockquote>" : "")];
SB({ g:"des", id:"libros", ey:"Resúmenes de libros", t:"Resúmenes de libros que todo ingeniero industrial debería leer", lead:"Veinticuatro libros de gestión, operaciones, psicología, comunicación y desarrollo personal, resumidos con sus ideas clave y cómo aplicarlos en el trabajo. Un resumen no reemplaza la lectura: úsalo para elegir cuál leer primero y para repasar.",
fig:[() => D.timeline([["1911", "Taylor"], ["1936", "Carnegie"], ["1967", "Drucker"], ["1984", "Goldratt · Cialdini"], ["1989", "Covey"], ["1996", "Womack y Jones"], ["2011", "Kahneman"], ["2018", "Clear"]], "Algunos de los libros resumidos, ordenados por año de publicación original."), () => D.matrix(["Primer año", "Más adelante"], ["Operaciones y gestión", "Personas y desarrollo"], [[["La meta · Lean Thinking · The Toyota Way", 1], ["Cómo ganar amigos · Hábitos atómicos · Los 7 hábitos", 2]], [["Out of the Crisis · El ejecutivo eficaz · Thinking in Systems", 3], ["Pensar rápido · Influence · Conversaciones cruciales", 4]]], "Una sugerencia de orden de lectura.")],
secs:[
BK("La meta", "Eliyahu M. Goldratt y Jeff Cox", 1984, "Operaciones · novela de negocios", "La meta de una empresa es ganar dinero, y la capacidad de todo el sistema está limitada por su restricción (cuello de botella). Mejorar cualquier otra cosa es una ilusión.", ["Contada como novela: Alex Rogo, gerente de una planta que la casa matriz quiere cerrar en tres meses, aprende con su antiguo profesor Jonah a pensar el sistema completo.", "Tres medidas: throughput (dinero que entra por ventas), inventario y gasto operativo. Hay que aumentar el primero y reducir los otros dos.", "Una hora perdida en el cuello de botella es una hora perdida para todo el sistema; una hora ganada en un no cuello de botella es un espejismo.", "Los cinco pasos: identificar la restricción, explotarla, subordinar todo a ella, elevarla y volver a empezar.", "La excursión de Herbie: una fila de exploradores avanza al ritmo del más lento; las fluctuaciones estadísticas y los eventos dependientes generan inventario y atrasos."], "<p>En cualquier proyecto de capacidad, encuentra primero la restricción (donde se acumula inventario antes y faltan materiales después). Asegura que nunca pare por falta de material, personas o mantención, y que no procese productos defectuosos. Solo después piensa en invertir.</p>", "«Una hora perdida en el cuello de botella es una hora perdida para todo el sistema».") ,
BK("Lean Thinking", "James P. Womack y Daniel T. Jones", 1996, "Operaciones · lean", "Toda organización puede aplicar los principios del sistema de producción Toyota para eliminar desperdicio y crear valor para el cliente.", ["Cinco principios: definir el valor desde el cliente, identificar el flujo de valor, hacer que fluya, producir según el tirón (pull) del cliente y buscar la perfección.", "Casos de empresas estadounidenses, alemanas y japonesas que transformaron sus operaciones.", "El término «lean» se popularizó con su libro anterior, <i>La máquina que cambió el mundo</i> (1990), basado en el estudio del MIT sobre la industria automotriz."], "<p>Haz un VSM del proceso, mide el tiempo que agrega valor frente al lead time total y ataca primero las esperas e inventarios entre etapas.</p>", ""),
BK("The Toyota Way", "Jeffrey K. Liker", 2004, "Operaciones · cultura", "El éxito de Toyota no está en sus herramientas (kanban, andon) sino en una cultura de mejora continua y respeto por las personas, sostenida por 14 principios.", ["Decidir con visión de largo plazo, aunque afecte resultados de corto plazo.", "Crear flujo continuo para que los problemas salgan a la superficie.", "Detener la línea para arreglar los problemas a la primera (jidoka).", "Las tareas estandarizadas son la base de la mejora.", "Ir y ver por uno mismo (genchi genbutsu).", "Decidir lentamente por consenso, considerando todas las opciones, e implementar rápidamente.", "Convertirse en una organización que aprende mediante la reflexión (hansei) y la mejora continua (kaizen)."], "<p>Antes de copiar una herramienta lean, pregúntate si existe la cultura que la sostiene: ¿se puede detener la línea sin castigo?, ¿los supervisores enseñan a resolver problemas?</p>", ""),
BK("Out of the Crisis", "W. Edwards Deming", 1982, "Calidad · gestión", "La mayoría de los problemas de calidad (Deming estimaba la gran mayoría) se deben al sistema, que es responsabilidad de la gerencia, no a los trabajadores.", ["Los 14 puntos para la gerencia: constancia en el propósito, dejar de depender de la inspección masiva, eliminar el miedo, romper barreras entre departamentos, eliminar metas numéricas arbitrarias, educación y automejora para todos.", "Distinguir causas comunes (del sistema) de causas especiales (asignables) con cartas de control.", "Las siete enfermedades mortales, como la falta de constancia y la evaluación anual del desempeño basada en resultados de corto plazo."], "<p>Cuando algo falla, antes de buscar al culpable, pregunta qué en el sistema permitió el error. Usa cartas de control para no reaccionar a la variación normal.</p>", "«Un mal sistema derrotará siempre a una buena persona» (frase atribuida a Deming).") ,
BK("El ejecutivo eficaz", "Peter F. Drucker", 1967, "Gestión · productividad personal", "La eficacia se aprende, y consiste en hacer las cosas correctas, no solo hacer bien las cosas.", ["Conoce en qué se va tu tiempo: regístralo y elimina lo que no aporta.", "Enfócate en la contribución: ¿qué puedo aportar yo que impacte en los resultados de la organización?", "Construye sobre las fortalezas (tuyas y de tu equipo), no sobre las debilidades.", "Concéntrate en pocas prioridades y haz primero lo primero.", "Toma pocas decisiones, pero importantes, con un proceso riguroso."], "<p>Registra tu tiempo durante dos semanas. Probablemente descubrirás que dedicas poco tiempo a las tareas que realmente generan resultados.</p>", "«No hay nada tan inútil como hacer con gran eficiencia algo que no debería hacerse en absoluto» (Drucker, Harvard Business Review, 1963).") ,
BK("Thinking in Systems", "Donella H. Meadows", 2008, "Pensamiento sistémico", "Los sistemas se comportan según su estructura de stocks, flujos y ciclos de retroalimentación; para cambiar resultados hay que cambiar la estructura.", ["Stocks (inventarios, personas, dinero) y flujos (entradas y salidas).", "Ciclos de refuerzo (crecen o colapsan) y de equilibrio (buscan una meta).", "Los retardos generan oscilaciones: por ejemplo, el efecto látigo en la cadena de suministro.", "Puntos de apalancamiento: los cambios en metas, reglas y paradigmas tienen más efecto que ajustar parámetros."], "<p>Ante un problema que vuelve una y otra vez, dibuja el diagrama de ciclos causales: suele haber un retardo o un incentivo que lo reproduce.</p>", ""),
BK("Pensar rápido, pensar despacio", "Daniel Kahneman", 2011, "Psicología · decisiones", "Tenemos dos sistemas de pensamiento: uno rápido e intuitivo, propenso a sesgos, y otro lento y analítico, que se cansa. Las buenas decisiones requieren saber cuándo desconfiar de la intuición.", ["Heurísticas y sesgos: anclaje, disponibilidad, representatividad, exceso de confianza.", "Teoría prospectiva: la aversión a la pérdida y la dependencia del punto de referencia.", "La falacia de planificación y la vista externa (comparar con proyectos similares).", "Efecto de encuadre: la forma de presentar cambia la decisión."], "<p>Para estimaciones de plazo y costo, usa datos de proyectos anteriores (clase de referencia). En decisiones grandes, escribe tus supuestos y pide a alguien que los cuestione.</p>", ""),
BK("Influence: The Psychology of Persuasion", "Robert B. Cialdini", 1984, "Psicología · persuasión", "Existen principios universales que hacen que las personas digan que sí, y conocerlos permite usarlos con ética y defenderse de quien los usa para manipular.", ["Reciprocidad, compromiso y coherencia, prueba social, simpatía, autoridad y escasez; en ediciones posteriores, unidad.", "Cada principio es un atajo mental útil, que también puede ser explotado.", "Defensa: detectar cuando un principio se activa artificialmente."], "<p>Ver la página «Influencia y persuasión» de esta sección.</p>", ""),
BK("Cómo ganar amigos e influir sobre las personas", "Dale Carnegie", 1936, "Relaciones humanas", "Las personas responden mejor al aprecio sincero, al interés genuino y al respeto que a la crítica y la discusión.", ["No critiques, no condenes ni te quejes.", "Muestra aprecio honrado y sincero.", "Interésate de verdad por los demás; recuerda su nombre; escucha.", "La única forma de ganar una discusión es evitarla.", "Muestra respeto por las opiniones ajenas; nunca digas «usted está equivocado».", "Si te equivocas, admítelo rápida y enfáticamente.", "Deja que la otra persona sienta que la idea es suya."], "<p>En terreno, aprende los nombres de los operadores, pregunta por su experiencia y reconoce sus aportes. Las mejoras se implementan a través de personas que confían en ti.</p>", ""),
BK("Los 7 hábitos de la gente altamente efectiva", "Stephen R. Covey", 1989, "Desarrollo personal", "La efectividad nace del carácter y de principios, y avanza de la dependencia a la independencia y luego a la interdependencia.", ["1. Ser proactivo: actuar en tu círculo de influencia.", "2. Comenzar con un fin en mente.", "3. Poner primero lo primero (cuadrante de lo importante no urgente).", "4. Pensar en ganar-ganar.", "5. Procurar primero comprender y después ser comprendido.", "6. Sinergizar.", "7. Afilar la sierra: cuidar cuerpo, mente, relaciones y espíritu."], "<p>El hábito 5 es oro para un ingeniero: antes de presentar tu solución, entiende cómo ve el problema el otro.</p>", ""),
BK("Hábitos atómicos", "James Clear", 2018, "Desarrollo personal", "Los grandes resultados vienen de pequeñas mejoras sostenidas; los hábitos se diseñan mediante el entorno, no solo con fuerza de voluntad.", ["Mejorar 1 % diario se acumula enormemente con el tiempo (interés compuesto aplicado a hábitos).", "Las cuatro leyes del cambio de conducta: hazlo obvio, atractivo, sencillo y satisfactorio.", "Concéntrate en sistemas, no en metas; y en identidad («soy una persona que lee»), no solo en resultados.", "Encadenar hábitos: «después de servir el café, leo 10 páginas»."], "<p>Diseña tu entorno de estudio: libro sobre el escritorio, teléfono en otra habitación. Lo mismo vale en planta: un estándar visual hace obvio el comportamiento correcto.</p>", ""),
BK("Mindset", "Carol S. Dweck", 2006, "Psicología · aprendizaje", "La creencia de que la inteligencia se puede desarrollar (mentalidad de crecimiento) produce más aprendizaje y resiliencia que creer que es fija.", ["Mentalidad fija: evita desafíos, se rinde, ve el esfuerzo como inútil, se siente amenazada por el éxito ajeno.", "Mentalidad de crecimiento: busca desafíos, persiste, aprende de la crítica, se inspira con el éxito ajeno.", "Elogiar el esfuerzo y la estrategia, no el talento."], "<p>Al dar feedback a tu equipo, destaca el proceso («el análisis de causa raíz fue muy riguroso») más que el talento («eres muy inteligente»).</p>", ""),
BK("La inteligencia emocional", "Daniel Goleman", 1995, "Psicología", "Las capacidades emocionales (autoconocimiento, autorregulación, motivación, empatía y habilidades sociales) influyen tanto como el coeficiente intelectual en el éxito profesional.", ["El «secuestro de la amígdala»: reacciones emocionales que anulan el razonamiento.", "Las emociones se pueden reconocer y manejar con práctica.", "En liderazgo, las competencias emocionales distinguen a los líderes destacados."], "<p>Identifica tus detonantes (críticas en público, atrasos ajenos) y define una respuesta previa: respirar, preguntar, postergar la decisión.</p>", ""),
BK("Obtenga el sí", "Roger Fisher, William Ury y Bruce Patton", 1981, "Negociación", "Se puede negociar sin ceder ni pelear: con método, enfocado en intereses y criterios objetivos.", ["Separar a las personas del problema.", "Enfocarse en intereses, no en posiciones.", "Inventar opciones de mutuo beneficio.", "Insistir en criterios objetivos.", "Conocer tu MAAN (mejor alternativa a un acuerdo negociado)."], "<p>Ver la página «Negociación y liderazgo» en Saberes.</p>", ""),
BK("Conversaciones cruciales", "Kerry Patterson, Joseph Grenny, Ron McMillan y Al Switzler", 2002, "Comunicación", "Las conversaciones donde hay opiniones distintas, mucho en juego y emociones intensas se pueden manejar con habilidades específicas.", ["Empezar desde el corazón: ¿qué quiero realmente para mí, para el otro y para la relación?", "Detectar cuándo la conversación se vuelve crucial y cuándo el otro se siente inseguro (silencio o violencia verbal).", "Crear seguridad: propósito mutuo y respeto mutuo.", "Dominar tus historias: separar hechos de interpretaciones.", "Exponer tu camino: compartir hechos, contar tu historia, preguntar por la del otro, hablar con tentatividad, alentar a probar."], "<p>Útil para hablar con un supervisor que no cumple estándares de seguridad, con un proveedor que falla o con tu jefe sobre una carga excesiva.</p>", ""),
BK("Las cinco disfunciones de un equipo", "Patrick Lencioni", 2002, "Equipos · liderazgo", "Los equipos fallan por cinco disfunciones encadenadas: falta de confianza, temor al conflicto, falta de compromiso, evasión de responsabilidad y desatención a los resultados.", ["Contado como fábula de una gerenta que reconstruye un equipo directivo.", "Sin confianza basada en la vulnerabilidad, no hay debate honesto.", "Sin debate, no hay compromiso real con las decisiones.", "Sin compromiso, nadie exige a otros.", "Sin exigencia mutua, priman los intereses individuales sobre los resultados del equipo."], "<p>En tus reuniones, invita a discrepar y cierra con compromisos claros: qué, quién y cuándo.</p>", ""),
BK("El hombre en busca de sentido", "Viktor E. Frankl", 1946, "Filosofía · resiliencia", "El psiquiatra Viktor Frankl relata su experiencia en campos de concentración nazis y concluye que encontrar sentido permite soportar casi cualquier circunstancia.", ["La última de las libertades humanas es elegir la actitud ante las circunstancias.", "Logoterapia: la búsqueda de sentido como motivación principal del ser humano.", "El sentido se encuentra en el trabajo, en el amor y en la actitud ante el sufrimiento inevitable."], "<p>En momentos de presión profesional (proyectos fallidos, despidos, crisis), conectar el trabajo con un propósito mayor da resiliencia.</p>", "«Quien tiene un porqué para vivir puede soportar casi cualquier cómo» (Frankl citando a Nietzsche)."),
BK("Getting Things Done (Organízate con eficacia)", "David Allen", 2001, "Productividad", "La mente es para tener ideas, no para guardarlas: un sistema confiable de captura y organización libera atención y reduce el estrés.", ["Cinco pasos: capturar, aclarar, organizar, reflexionar (revisión semanal) y hacer.", "Definir la «próxima acción física» de cada proyecto.", "Regla de los dos minutos.", "Listas por contexto (en la oficina, en terreno, llamadas)."], "<p>Anota todo compromiso en un solo sistema (cuaderno o aplicación) y haz una revisión semanal el viernes.</p>", ""),
BK("Trabajo profundo (Deep Work)", "Cal Newport", 2016, "Productividad · concentración", "La capacidad de concentrarse sin distracciones en tareas cognitivamente exigentes es cada vez más escasa y valiosa.", ["El trabajo superficial (correos, reuniones, mensajes) es fácil de replicar y aporta poco valor.", "Programa bloques de concentración y protégelos.", "Aburrirse sin buscar el teléfono entrena la atención.", "Reduce redes sociales que no aportan a tus metas."], "<p>Bloquea dos mañanas por semana para análisis, modelos e informes, con el correo cerrado.</p>", ""),
BK("Empieza con el porqué (Start with Why)", "Simon Sinek", 2009, "Liderazgo · comunicación", "Los líderes que inspiran comunican desde el propósito (por qué), luego el cómo y al final el qué.", ["El círculo dorado: por qué, cómo, qué.", "Las personas no compran lo que haces, sino por qué lo haces.", "La confianza surge de valores compartidos."], "<p>Al presentar un cambio, empieza por el propósito («queremos que nadie más se lesione en esta prensa») antes del detalle técnico.</p>", ""),
BK("Drive", "Daniel H. Pink", 2009, "Motivación", "Para el trabajo creativo, los incentivos de premio y castigo funcionan peor que la motivación intrínseca, basada en autonomía, maestría y propósito.", ["Motivación 1.0 (supervivencia), 2.0 (premios y castigos) y 3.0 (intrínseca).", "Las recompensas condicionadas pueden reducir la creatividad y fomentar atajos.", "Basado en la teoría de la autodeterminación de Deci y Ryan."], "<p>Da a tu equipo margen para decidir cómo hacer el trabajo, oportunidades para mejorar y explica el sentido de lo que hacen.</p>", ""),
BK("The Principles of Scientific Management", "Frederick W. Taylor", 1911, "Historia · estudio del trabajo", "El trabajo puede estudiarse científicamente para encontrar el mejor método, seleccionar y capacitar a las personas y dividir responsabilidades entre dirección y operarios.", ["Estudio de tiempos y movimientos.", "Selección y entrenamiento científico de los trabajadores.", "Cooperación entre dirección y trabajadores.", "Fue criticado por deshumanizar el trabajo, pero sentó las bases de la ingeniería industrial."], "<p>Léelo para entender el origen de la profesión y sus límites: el método importa, pero también la participación de quien hace el trabajo.</p>", ""),
BK("El principio de la pirámide", "Barbara Minto", 1987, "Comunicación escrita", "Las ideas se comprenden mejor cuando se presentan de arriba hacia abajo: primero la conclusión y luego los argumentos que la sostienen, agrupados de forma lógica.", ["Estructura SCQA: situación, complicación, pregunta, respuesta.", "Agrupaciones MECE de argumentos.", "Orden deductivo o inductivo según el caso."], "<p>Aplícalo a cada informe ejecutivo y a cada correo importante: la primera frase debe contener la conclusión.</p>", ""),
BK("Antifrágil", "Nassim Nicholas Taleb", 2012, "Riesgo · decisiones", "Algunos sistemas no solo resisten la volatilidad, sino que se benefician de ella; conviene diseñar organizaciones y carreras así.", ["Frágil, robusto y antifrágil.", "Evitar riesgos de ruina (pérdidas irreversibles).", "Opcionalidad: muchas apuestas pequeñas con poco costo y gran beneficio potencial.", "Desconfiar de modelos que ignoran eventos extremos («cisnes negros», tema de su libro de 2007)."], "<p>En planificación, considera escenarios extremos (falla del proveedor único, terremoto, corte de energía) y crea redundancias en lo crítico.</p>", "")],
tips:["Lee con un lápiz: subraya y escribe en el margen cómo aplicarías cada idea.", "Después de cada libro, escribe una página con las 5 ideas principales y una acción concreta.", "Alterna libros técnicos con libros de personas y de desarrollo personal.", "Veinte minutos al día son más de 15 libros al año.", "Si un libro no te aporta después de 50 páginas, déjalo: hay demasiados buenos esperando."],
cita:["Hoy un lector, mañana un líder.", "Atribuida a Margaret Fuller"], rel:["bibliografia", "pensadores", "habilidades-blandas"] });
